function plot(id,lines,xmin,xmax,ymin,ymax,log,xticks,unit){const {c,w,h}=canvasSetup($(id));let l=44,r=w-18,top=16,bottom=h-32;const x=v=>l+(log?Math.log(v/xmin)/Math.log(xmax/xmin):(v-xmin)/(xmax-xmin))*(r-l),y=v=>bottom-(v-ymin)/(ymax-ymin)*(bottom-top);c.font='12px Segoe UI';c.fillStyle='#607080';c.strokeStyle='#e2e8e9';for(let i=0;i<=4;i++){let val=ymin+(ymax-ymin)*i/4,yy=y(val);c.beginPath();c.moveTo(l,yy);c.lineTo(r,yy);c.stroke();c.fillText(val.toFixed(0),7,yy+4);}for(const v of xticks){c.fillText(v>=1000?(v/1000)+'k':v,x(v)-8,h-12);}c.save();c.beginPath();c.rect(l,top,r-l,bottom-top);c.clip();for(const line of lines){c.strokeStyle=line.color;c.lineWidth=line.width||2;c.beginPath();line.points.forEach(([xx,yy],i)=>i?c.lineTo(x(xx),y(yy)):c.moveTo(x(xx),y(yy)));c.stroke();}c.restore();c.fillText(unit,w-25,h-12);}
