async function startAudio(){const Context=window.AudioContext||window.webkitAudioContext;if(!Context)throw Error('Audio playback is unsupported in this browser.');const ctx=new Context();await ctx.resume();audio={ctx,nodes:[]};restartAudio();$('listen').textContent='■ Stop sound';setSpinning(true);}
