{id:'quiet',name:'Quiet 140',tag:'Wide, gently swept blades',description:'140 mm · 9 blades',p:{...M.defaults,diameter:140,hub:42,blades:9,chord:28,pitch:26,twist:16,sweep:28,rpm:1100}},
{id:'pressure',name:'Pressure 120',tag:'Broad blades, higher pitch',description:'120 mm · 9 blades',p:{...M.defaults,hub:44,blades:9,chord:32,pitch:40,twist:5,sweep:12,rpm:1900}},
{id:'compact',name:'Compact 80',tag:'A smaller starting point',description:'80 mm · 7 blades',p:{...M.defaults,diameter:80,hub:28,blades:7,chord:17,pitch:32,twist:10,sweep:15,rpm:2200}}
