$('side').onclick=()=>{yaw=Math.PI/2;tilt=0;zoom=1;setView('side');drawRotor();};for(const id of ['front','iso']){const original=$(id).onclick;$(id).onclick=()=>{original();setView(id);};}
$('finish').onchange=()=>{visual.finish=$('finish').value;drawRotor();};for(const [id,key] of [['wireframe','wire'],['exploded','exploded']])$(id).onclick=()=>{visual[key]=!visual[key];$(id).setAttribute('aria-pressed',visual[key]);drawRotor();};
$('zoom-in').onclick=()=>{zoom=Math.min(1.6,zoom+.1);drawRotor();};$('zoom-out').onclick=()=>{zoom=Math.max(.55,zoom-.1);drawRotor();};$('sound-play').onclick=()=>$('listen').click();
